1	<?php
2	
3	namespace AtrioTeam\Marvin\App\Http\Livewire;
4	
5	use Exception;
6	use Throwable;
7	use AtrioTeam\Marvin\App\Models\Gallery;
8	use Livewire\Component;
9	use AtrioTeam\Marvin\App\Models\GalleryLang;
10	use Illuminate\Support\Str;
11	use Livewire\WithFileUploads;
12	use Illuminate\Support\Facades\View;
13	use AtrioTeam\Marvin\App\Html\Purifier;
14	use Illuminate\Support\Facades\Storage;
15	
16	class FileInputFile extends Component
17	{
18	    use WithFileUploads;
19	    use FileInputTrait;
20	
21	    /**
22	     * Nome del campo file, diventa item_type nella tabella galleries
23	     */
24	    public $name;
25	
26	    /**
27	     * Nome pubblico del campo per html
28	     */
29	    public $publicName;
30	
31	    /**
32	     * Modello principale a cui il file è collegato
33	     */
34	    public $item;
35	
36	    /**
37	     * FIle corrente (temporaneo o meno)
38	     */
39	    public $file;
40	
41	
42	    /**
43	     * Configurazione  (specifica del campo file all'interno della funzione, es 'img_1')
44	     */
45	    public $config;
46	
47	    /**
48	     * Codice funzione
49	     */
50	    public $functionCode;
51	
52	
53	    /**
54	     * Elenco lingue
55	     */
56	    public $langList;
57	
58	
59	    /**
60	     * Id lingua corrente (in conseguenza di azioni su tab)
61	     */
62	    public $currentLgId;
63	
64	
65	    /**
66	     * Campi e valori in lingua
67	     */
68	    public $langFieldsValues;
69	    public $langFields;
70	
71	
72	    /**
73	     * Campi e valori non in lingua
74	     */
75	    public $fieldsValues;
76	    public $fields;
77	
78	
79	    /**
80	     * Proprietà file relativa al campo di upload
81	     */
82	    public $file_upload;
83	
84	    /**
85	     * token di creazione
86	     */
87	    public $createdToken;
88	
89	
90	    /**
91	     * Flag per stato di ordinamento
92	     * (in azione su componente padre)
93	     */
94	    public $parentOrdering;
95	
96	    public $parentLang;
97	
98	    /**
99	     * Qui il file è singolo
100	     */
101	    public $limitCount = 1;
102	
103	    /**
104	     * Didascalia quando l'elemento è in corso di ordinamento
105	     */
106	    public string $orderingCaption = '';
107	
108	
109	    /**
110	     * Eventi
111	     * Alcuni possono essere dedicati al padre
112	     */
113	    protected function getListeners()
114	    {
115	        return [
116	            'refreshOrderingStatus.' . $this->name => 'refreshOrderingStatus',
117	            // dedicato al refresh della configurazione widget
118	            'updateWidgetConfig' => 'updateWidgetConfig',
119	        ];
120	    }
121	
122	
123	    /**
124	     * Montaggio del componente
125	     */
126	    public function mount()
127	    {
128	        $this->parseConfig();
129	    }
130	
131	
132	    /**
133	     * Estrapolo dalla configurazione alcune informazioni
134	     * valorizzandole come proprietà del componente.
135	     */
136	    protected function parseConfig()
137	    {
138	        $config = $this->config;
139	
140	        // regole di default per validazione
141	        if (!array_key_exists('rules', $config)) {
142	            $config['rules'] = $this->defaultRules();
143	        }
144	
145	
146	        // eventuali campi aggiuntivi
147	        $this->langFields = array_key_exists('lang_fields', $config) ? $config['lang_fields'] : [];
148	        $this->fields = array_key_exists('fields', $config) ? $config['fields'] : [];
149	
150	        // memorizzo lista locales e id corrente
151	        $this->currentLgId = current(array_keys($this->langList));
152	
153	        // aggiorno alcune informazioni per assecondare vista
154	        //$this->file->values_tmp = $this->file->values;
155	        $this->fieldsValues = $this->file->values;
156	        foreach ($this->file->langs as $k => $rsLang) {
157	            $this->langFieldsValues[$rsLang->lang] = $rsLang->values;
158	        }
159	
160	        return $this->config = $config;
161	    }
162	
163	
164	    /**
165	     * Aggiorna il valore di un singolo campo testuale
166	     */
167	    public function updatedLangFieldsValues($value, $name)
168	    {
169	        //pulizia del valore in ingresso
170	        $purifier = app()->make(Purifier::class, [$this->functionCode]);
171	        $value = $purifier->clean($value);
172	
173	        $nameCp = explode('.', $name);
174	
175	        $lgId = $nameCp[0];
176	        $fieldName = $nameCp[1];
177	
178	        $rs = GalleryLang::where([['item_id', $this->file->id], ['lang', $lgId]])->first();
179	
180	        $currentValues = array_merge($rs->values ?? [], $rs->values_tmp);
181	
182	        $currentValues[$fieldName] = $value;
183	        $rs->values_tmp = $currentValues;
184	        $rs->save();
185	
186	        $this->currentLgId = $lgId;
187	    }
188	
189	
190	    /**
191	     * Aggiorna il valore di un singolo campo non in lingua
192	     */
193	    public function updatedFieldsValues($value, $name)
194	    {
195	        //pulizia del valore in ingresso
196	        $purifier = app()->make(Purifier::class, [$this->functionCode]);
197	        $value = $purifier->clean($value);
198	
199	        $rs = Gallery::find($this->file->id);
200	
201	        $currentValues = array_merge($rs->values, $rs->values_tmp);
202	
203	        $currentValues[$name] = $value;
204	        $rs->values_tmp = $currentValues;
205	        $rs->save();
206	    }
207	
208	
209	    /**
210	     * Annullamento caricamento.
211	     * Per file nuovo non ancora confermato.
212	     */
213	    public function undoUpload()
214	    {
215	        $this->resetValidation();
216	        $this->file->delete();
217	        $this->file = null;
218	
219	        $this->dispatch('refresh');
220	    }
221	
222	
223	    /**
224	     * Caricamento di un nuovo file.
225	     * Può avvenire per un file nuovo non ancora confermato
226	     * o per un file precedentemente caricato e confermato.
227	     */
228	    public function updatedFileUpload()
229	    {
230	        // validazione
231	        $this->validate([
232	            'file_upload' => $this->config['rules'],
233	        ], [
234	            'file_upload.mimes' => 'Il file non è consentito. Sono ammessi: ' . $this->allowedMimes($this->config) . '.',
235	        ], [
236	            'file_upload' => 'Il file'
237	        ]);
238	
239	
240	        // memorizzo nuovo file
241	        $path = $this->file_upload->getPath() . '/' . $this->file_upload->getFilename();
242	
243	        try {
244	            $url = str_replace(url('/'), '', $this->file_upload->temporaryUrl());
245	        } catch (Throwable $e) {
246	            $url = '';
247	        }
248	
249	        // salvo
250	        $g = Gallery::findOrFail($this->file->id);
251	        $g->image_new = json_encode([
252	            'name' => $this->file_upload->getClientOriginalName(),
253	            'path' => $path,
254	            'url' => $url,
255	        ]);
256	        $g->created_token = $this->createdToken;
257	        $g->save();
258	
259	        $this->file = $g;
260	    }
261	
262	
263	    /**
264	     * Annulla sostituzione del file.
265	     * Eseguito solo per file già caricati e confermati
266	     * precedentemente.
267	     */
268	    public function undoFileReplace()
269	    {
270	        if ($this->file->status != 'Y') {
271	            abort(404);
272	        }
273	
274	        $this->resetValidation();
275	        $this->file->image_new = null;
276	        $this->file->save();
277	    }
278	
279	
280	    /**
281	     * Cancella file
282	     */
283	    public function markDelete()
284	    {
285	        $this->resetValidation();
286	
287	        // aggiorno flag e colonna token
288	        $this->file->mark_delete = 'Y';
289	        $this->file->created_token = $this->createdToken;
290	        $this->file->save();
291	    }
292	
293	
294	    /**
295	     * Annulla Cancellazione file
296	     */
297	    public function undoMarkDelete()
298	    {
299	        $this->resetValidation();
300	
301	        $this->file->mark_delete = 'N';
302	        $this->file->save();
303	    }
304	
305	
306	    /**
307	     * Evento emesso da parent al cambio della modalità
308	     * di ordinamento
309	     * (on/off)
310	     */
311	    public function refreshOrderingStatus(bool $newStatus)
312	    {
313	        $this->parentOrdering = $newStatus;
314	    }
315	
316	    /**
317	     * Render
318	     */
319	    public function render()
320	    {
321	        /**
322	         * Se non ho file (es. in seguito a cancellazione)
323	         * ritorno stringa vuota.
324	         */
325	        if ($this->file === null) {
326	            return '<div></div>';
327	        }
328	
329	
330	        /**
331	         * mostro didascalia in caso stia ordinando.
332	         * Se ho campi in lingua, recupero il primo campo nella prima lingua,
333	         * altrimenti primo campo non in lingua
334	         */
335	        $this->orderingCaption = '';
336	        if ($this->parentOrdering) :
337	
338	            $this->orderingCaption = '-';
339	
340	        if ($this->langFields) {
341	            $firstField = current($this->langFields)['name'];
342	            $firstLang = current($this->langFieldsValues);
343	            if (!empty($firstLang[$firstField])) {
344	                $this->orderingCaption = $firstLang[$firstField];
345	            }
346	        } elseif ($this->fields) {
347	            $firstField = current($this->fields)['name'];
348	
349	            if (!empty($this->fieldsValues[$firstField])) {
350	                $this->orderingCaption = $this->fieldsValues[$firstField];
351	            }
352	        }
353	
354	        $this->orderingCaption = Str::words($this->orderingCaption, 5);
355	        endif;
356	
357	
358	        /**
359	         * Aggiorno proprietà sul file corrente prima di andare in output
360	         */
361	        $imageNew = json_decode($this->file->image_new);
362	        $this->file->url = Storage::disk('public')->url($this->file->url);
363	        if ($imageNew) {
364	            $this->file->url = $imageNew->url;
365	            $this->file->path = $imageNew->url;
366	            $this->file->name = $imageNew->name;
367	        }
368	
369	        View::addLocation(__DIR__ . '/../../../resources/views/components');
370	
371	        return view('file_input_file', []);
372	    }
373	
374	
375	    /**
376	     * Refresh della configurazione (quando sono in input widget)
377	     * Al selettore di una nuova tipologia o al load, viene inviata la nuova
378	     * configurazione specifica per la tipologia, per uniformare le logiche.
379	     * Poichè l'array in ingresso contiene tutti i campi file usati da quel widget (es. img_1, img_2, etc..), dobbiamo
380	     * estrarre dalla configurazione passata la configurazione specifica per quel campo. (es. img_1)
381	     *
382	     * @param array $newConfig la configurazione della nuova tipologia di widget (comprensiva di tutti i campi!)
383	     */
384	    public function updateWidgetConfig(array $selectedWidgetConfig)
385	    {
386	        // Se la configurazione passata non contiene il campo corrente, non faccio niente.
387	        // Tutti i campi vengono notificati, (tutte le n immagini del widget), ma non è detto che la configurazione
388	        // in ingresso contenga la configurazione per questo campo.
389	        if (!array_key_exists($this->name, $selectedWidgetConfig)) {
390	            return;
391	        }
392	
393	        // aggiorno la configurazione
394	        $this->config = $selectedWidgetConfig[$this->name];
395	
396	        // reparsing per valorizzare altre proprietà che mi servono nel render
397	        $this->parseConfig();
398	    }
399	}
