1	<?php
2	
3	namespace AtrioTeam\Marvin\App\Http\Livewire;
4	
5	use Storage;
6	use Exception;
7	use Throwable;
8	use AtrioTeam\Marvin\App\Models\Gallery;
9	use AtrioTeam\Marvin\App\Models\GalleryLang;
10	use Livewire\Component;
11	use Livewire\WithFileUploads;
12	use Illuminate\Support\Facades\View;
13	use Illuminate\Support\Facades\Validator;
14	
15	class FileInput extends Component
16	{
17	    use WithFileUploads;
18	    use FileInputTrait;
19	
20	
21	    /**
22	     * Modello cui l'input appartiene
23	     */
24	    public $item;
25	
26	    /**
27	     * Configurazione totale della funzione
28	     */
29	    public $config;
30	
31	    /**
32	     * Configurazione specifica del campo file all'interno della funzione
33	     */
34	    public $fileConfig;
35	
36	    /**
37	     * Nome del campo file, diventa item_type nella tabella galleries
38	     */
39	    public $name;
40	
41	    /**
42	     * Nome pubblico del campo per html
43	     */
44	    public $publicName;
45	
46	    /**
47	     * Elenco dei file caricati (alla selezione)
48	     */
49	    public $files = [];
50	
51	    /**
52	     * Tutti i file correntemente caricati
53	     * (attraverso anche selezioni multiple)
54	     */
55	    public $currentFiles = [];
56	
57	
58	    /**
59	     * Elenco file caricati precedentemente
60	     */
61	    public $previousFiles = [];
62	
63	
64	    /**
65	     * Token di identificazione lato server della richiesta
66	     */
67	    public $createdToken;
68	
69	
70	    /**
71	     * Lang,se valorizzato il file è in lingua
72	     */
73	    public $parentLang;
74	
75	
76	    /**
77	     * Elenco delle lingue
78	     */
79	    public $langList;
80	
81	
82	    /**
83	     * Numero di file
84	     */
85	    public $count;
86	    public $limitCount;
87	    // serve solo per validazione
88	    public $newCount;
89	
90	
91	    /**
92	     * Flag per modalità di ordinamento
93	     * @var boolean
94	     */
95	    public $ordering = false;
96	
97	
98	    /**
99	     * Elenco posizioni correnti dei file
100	     */
101	    public $currentOrder;
102	
103	
104	    /**
105	     * Messaggio di info per upload
106	     */
107	    public $uploadInfoMessage;
108	
109	    /**
110	     * Eventi
111	     */
112	    protected $listeners = [
113	        'refresh' => 'refresh',
114	        // dedicato al refresh della configurazione widget
115	        'updateWidgetConfig' => 'updateWidgetConfig',
116	    ];
117	
118	
119	    /**
120	     * Mount del componente
121	     */
122	    public function mount()
123	    {
124	        // recupero token di creazione
125	        $this->createdToken = app('marvinCreatedToken');
126	
127	        // pulisce eventuali dati temporanei precedenti
128	        $this->previousFiles = Gallery::where([
129	            ['item_table', $this->item->getTable()],
130	            ['item_id', $this->item->id],
131	            ['item_type', $this->name],
132	            ['status', 'Y'],
133	        ])->orderBy('position')->get()->map(function ($item) {
134	            $item->image_new = null;
135	            $item->mark_delete = 'N';
136	            $item->values_tmp = [];
137	            $item->save();
138	
139	            foreach ($item->langs as $itemLang) {
140	                $itemLang->values_tmp = [];
141	                $itemLang->save();
142	            }
143	
144	            return $item;
145	        });
146	
147	
148	        /**
149	         * Recupero alcuni valori dalla configurazione
150	         */
151	        $this->fileConfig = $this->loadFileConfig($this->config);
152	
153	
154	        /**
155	         * Creo nome pubblico che tenga conto di eventuale
156	         * campo in lingua
157	         */
158	        $this->publicName = $this->name;
159	        if ($this->parentLang) {
160	            $this->publicName .= '_' . $this->parentLang;
161	        }
162	    }
163	
164	
165	    public function render()
166	    {
167	        View::addLocation(__DIR__ . '/../../../resources/views/components');
168	
169	        $this->loadFileList();
170	
171	        return view('file_input');
172	    }
173	
174	
175	    /**
176	     * Recupero elenco complessivo dei file.
177	     * Normalizzo alcuni dati per avere meno condizioni in output
178	     */
179	    protected function loadFileList()
180	    {
181	
182	        // file precedenti
183	        $previousFiles = Gallery::where([
184	            ['item_table', $this->item->getTable()],
185	            ['item_id', $this->item->id],
186	            ['item_type', $this->name],
187	            ['status', 'Y'],
188	            ['parent_lang', $this->parentLang],
189	        ])->orderBy('position')->get()->map(function ($item) {
190	            return $item;
191	        });
192	
193	        //  tutti i file temporanei per la voce caricati nella stessa sessione
194	        $tempFiles = Gallery::where([
195	            ['item_table', $this->item->getTable()],
196	            ['item_id', $this->item->id],
197	            ['item_type', $this->name],
198	            ['status', 'T'],
199	            ['parent_lang', $this->parentLang],
200	            ['created_token', $this->createdToken],
201	        ])->orderBy('position')->get()->map(function ($item) {
202	            $imageNew = json_decode($item->image_new);
203	            $item->url = $imageNew->url;
204	            $item->path = $imageNew->url;
205	            return $item;
206	        });
207	
208	
209	        // unisco i due elenchi
210	        $this->currentFiles = $previousFiles->merge($tempFiles)->sortBy('position');
211	        $this->count = $this->currentFiles->count();
212	    }
213	
214	
215	    /**
216	     * Evento di caricamento nuovi file
217	     */
218	    public function updatedFiles()
219	    {
220	
221	        // recupero file già caricati
222	        $previous = Gallery::where([
223	            ['item_table', $this->item->getTable()],
224	            ['item_id', $this->item->id],
225	            ['item_type', $this->name],
226	            ['parent_lang', $this->parentLang],
227	        ])->where(function ($query) {
228	            $query
229	                ->where('status', 'Y')
230	                ->orWhere(function ($query) {
231	                    $query->where('status', 'T')->where('created_token', $this->createdToken);
232	                });
233	        })->get();
234	        $position = (int)$previous->max('position');
235	        $count = $previous->count() + count($this->files);
236	
237	        // eseguo validazione
238	        $this->validate([
239	            'files.*' => $this->fileConfig['rules'],
240	            'newCount' => function ($attribute, $value, $fail) use ($count) {
241	
242	                // conto file già presenti più quello in arrivo
243	                if ($this->limitCount && $count > $this->limitCount) {
244	                    $fail('Il numero totale di file supera il limite consentito. Seleziona meno file.');
245	                }
246	            },
247	        ], [
248	            'files.*.mimes' =>
249	            $this->limitCount > 1
250	                ? 'Uno o più file caricati non sono consentiti. Sono ammessi: ' . $this->allowedMimes($this->fileConfig) . '.'
251	                : 'Il file caricato non è consentito. Sono ammessi: ' . $this->allowedMimes($this->fileConfig) . '.',
252	        ], [
253	            'files' => 'Ogni file'
254	        ]);
255	
256	
257	        /**
258	         * Salvo i file
259	         */
260	        foreach ($this->files as $key => $file) {
261	            try {
262	                $url = $file->temporaryUrl();
263	            } catch (Throwable $e) {
264	                $url = '';
265	            }
266	
267	            $g = new Gallery();
268	            $g->image_new = json_encode([
269	                'name' => $file->getClientOriginalName(),
270	                'path' => $file->getPath() . '/' . $file->getFilename(),
271	                'url' => str_replace(url('/'), '', $url),
272	            ]);
273	            $g->item_id = $this->item->id;
274	            $g->item_table = $this->item->getTable();
275	            $g->item_type = $this->name;
276	            $g->position = ++$position;
277	            $g->parent_lang = $this->parentLang;
278	            $g->created_token = $this->createdToken;
279	            $g->status = 'T';
280	            $g->mark_delete = 'N';
281	            $g->values = [];
282	            $g->values_tmp = [];
283	            $g->function_code = $this->config['function_code'];
284	            $g->save();
285	
286	            foreach ($this->langList as  $lgId => $info) {
287	                $gL = new GalleryLang();
288	                $gL->item_id = $g->id;
289	                $gL->lang = $lgId;
290	                $gL->values = [];
291	                $gL->values_tmp = [];
292	                $gL->save();
293	            }
294	        }
295	
296	
297	        /**
298	         * Memorizzo nuocvo conteggio
299	         */
300	        $this->count = $count;
301	    }
302	
303	
304	    /**
305	     * Refresh triggerato da singolo file in seguito a suo aggiornamento.
306	     * Per ora non fa ora
307	     */
308	    public function refresh()
309	    {
310	    }
311	
312	
313	    /**
314	     * Inizia ordinamento
315	     */
316	    public function startOrdering()
317	    {
318	        $this->ordering = true;
319	        // evento ad uso dei componenti figli
320	        $this->dispatch('refreshOrderingStatus.' . $this->name, $this->ordering);
321	    }
322	
323	    /**
324	     * Salva ordinamento
325	     */
326	    public function saveOrdering($newOrder)
327	    {
328	        $this->ordering = false;
329	
330	        $newOrderArray = explode(',', $newOrder);
331	        if (!is_array($newOrderArray)) {
332	            abort(404, "Order not valid [$newOrder]");
333	        }
334	
335	        // salvo nuovo ordinamento
336	        foreach ($newOrderArray as $position => $id) {
337	            Gallery::where('id', $id)->update([
338	                'position' => $position
339	            ]);
340	        }
341	
342	        // evento ad uso dei componenti figli
343	        $this->dispatch('refreshOrderingStatus.' . $this->name, $this->ordering);
344	    }
345	
346	    /**
347	     * Annulla ordinamento
348	     */
349	    public function cancelOrdering()
350	    {
351	        $this->ordering = false;
352	
353	        // evento ad uso dei componenti figli
354	        $this->dispatch('refreshOrderingStatus.' . $this->name, $this->ordering);
355	    }
356	
357	
358	    /**
359	     * Refresh della configurazione (quando sono in input widget)
360	     * Al selettore di una nuova tipologia, viene inviata la nuova
361	     * configurazione specifica per la tipologia, per uniformare le logiche.
362	     * L'evento viene raccolto da ogni input / campo, che deve a sua volta
363	     * estrarre dalla configurazione del widget la configurazione specifica per quel campo.
364	     *
365	     * @param array $selectedWidgetConfig la configurazione della nuova tipologia di widget (comprensiva di tutti i campi!)
366	     */
367	    public function updateWidgetConfig($selectedWidgetConfig)
368	    {
369	
370	        // chiamo il metodo che carica la configurazione specifica del campo, dipendente dal mio nome,
371	        // passandogli la configurazione forzata della nuova tipologia di widget
372	        $this->fileConfig = $this->loadFileConfig($selectedWidgetConfig);
