3	namespace Italamp\OnPage\Jobs;
4	
5	use OnPage\Api;
6	use Illuminate\Support\Str;
7	use Illuminate\Bus\Queueable;
8	use Illuminate\Support\Facades\Log;
9	use Illuminate\Support\Facades\Http;
10	use Illuminate\Queue\SerializesModels;
11	use Illuminate\Database\Eloquent\Model;
12	use Illuminate\Support\Facades\Storage;
13	use AtrioTeam\Marvin\App\Models\Gallery;
14	use Illuminate\Queue\InteractsWithQueue;
15	use Illuminate\Contracts\Queue\ShouldQueue;
16	use Illuminate\Foundation\Bus\Dispatchable;
17	use AtrioTeam\Marvin\App\Localization\LangManager;
18	
19	class SaveRemoteImage implements ShouldQueue
20	{
21	    use Dispatchable;
22	    use InteractsWithQueue;
23	    use Queueable;
24	    use SerializesModels;
25	
26	
27	    /**
28	     * The number of times the job may be attempted.
29	     *
30	     * @var int
31	     */
32	    public $tries = 3;
33	
34	    /**
35	     * Timeout
36	     */
37	    public $timeout = 240;
38	
39	    /**
40	     * Indicate if the job should be marked as failed on timeout.
41	     *
42	     * @var bool
43	     */
44	    public $failOnTimeout = true;
45	
46	    /**
47	     * Modello a cui si rfiersice
48	     */
49	    protected $model;
50	
51	    /**
52	     * Nome del campo file remoto
53	     */
54	    protected $remoteFieldName;
55	
56	    /**
57	     * Nome del campo locale corrispondente al campo remoto.
58	     * Se non passato, viene preso quello remoto
59	     */
60	    protected $localFieldName;
61	
62	    protected $locale;
63	
64	    protected $config;
65	
66	    protected $force;
67	
68	    /**
69	     * Create a new job instance.
70	     *
71	     * @param string $locale codice locale (es. it, en..)
72	     *
73	     * @return void
74	     */
75	    public function __construct(Model $model, $config, string $remoteFieldName, string $localFieldName, string $locale = null, bool $force = false)
76	    {
77	        $this->config = $config;
78	
79	        $this->model = $model;
80	
81	        $this->remoteFieldName = $remoteFieldName;
82	
83	        $this->localFieldName = $localFieldName ?: $remoteFieldName;
84	
85	        $this->locale = $locale;
86	
87	        $this->force = $force;
88	
89	        $this->queue = 'onpage_images';
90	    }
91	
92	
93	    /**
94	     * Execute the job.
95	     *
96	     * @return void
97	     */
98	    public function handle(\OnPage\Schema $api, LangManager $langManager)
99	    {
100	        // manually build remote file link to avoid querying api
101	        // @see https://acme-inc.onpage.it/api/storage/R417C0YAM90RF?name=icecream-spec.pdf
102	        $remoteValue = $this->model->hasFile($this->remoteFieldName, $langManager->idByPrefix($this->locale));
103	        // no file, stop here
104	        if ($remoteValue === false) {
105	            return;
106	        }
107	
108	        //$remoteValue = $this->locale ? $remoteValue['value'][$this->locale] : $remoteValue['value'];
109	
110	        // "this willk point to the original file"
111	        $link = 'https://' . config('onpage.endpoint') . '.onpage.it/api/storage/' . $remoteValue['token'] . '?name=' . $remoteValue['name'];
112	
113	
114	        // Save file record
115	        $file = Gallery::firstOrNew([
116	            'item_id' => $this->model->id,
117	            'item_table' => $this->model->getTable(),
118	            'item_type' => $this->localFieldName,
119	            'status' => 'Y',
120	            'parent_lang' => $this->locale ? $langManager->idByPrefix($this->locale) : 0,
121	        ]);
122	
123	        // stop if we have a file
124	        // if ($file->id) {
125	        //     return 0;
126	        // }
127	
128	
129	        // gets remote file from api
130	        // if file does not exists, stop here
131	        // $remoteItem = $api->query($this->remoteResourceName)->where('_id', $this->model->onpage_id)->first();
132	        // $remoteFile = $this->locale ? $remoteItem->val($this->remoteFieldName, $this->locale) : $remoteItem->val($this->remoteFieldName);
133	        // if (!$remoteFile) {
134	        //     return 0;
135	        // }
136	        // $link = $remoteFile->link(['x' => 1000]);
137	
138	        // download file (above link will trigger download)
139	        // timeout in seconds
140	        $response = Http::timeout(120)->get($link);
141	
142	        // se non ho avutop modifiche, mi fermo
143	        if ($this->force === false && is_array($file->extra) && array_key_exists('token', $file->extra) && $remoteValue['token'] ==  $file->extra['token']) {
144	            // log action
145	            Log::channel('onpage')->info('image skipped', [
146	                'gallery id' => $file->id
147	            ]);
148	            return;
149	        }
150	
151	
152	        // get marvin function config and file service
153	        $fileService = app('File');
154	
155	        // calculate filename
156	        $remoteName = pathinfo($remoteValue['name']);
157	        $localFilename = Str::slug($remoteName['filename']);
158	        $localFilename = str_replace('#', '-', $localFilename);
159	        $localFileName = $localFilename.'.'.$remoteName['extension'];
160	
161	        $relativePath = str_replace(Storage::disk('public')->path(''), '', $this->config['upload']['path'] . '/' . $this->model->id . '/' . $localFileName);
162	        $finalName = $fileService->fileRename(Storage::disk('public')->path($relativePath));
163	        $relativePath = dirname($relativePath) . '/' . $finalName;
164	
165	        // delete old image and all sizes, if exists
166	        // Must be done before saving new image on disk!!
167	        if ($file->id && $file->image) {
168	            $sizesConfig = array_key_exists('size', $this->config[$this->localFieldName]) ? $this->config[$this->localFieldName]['size'] : [];
169	            $fileService->delImgPrefix($file->image, dirname(Storage::disk('public')->path($relativePath)), $sizesConfig);
170	        }
171	
172	        // save local copy of the image
173	        Storage::disk('public')->put(dirname($relativePath) . '/' . $finalName, $response, 'public');
174	
175	        // fix permessi (v. https://github.com/laravel/framework/issues/42586)
176	        chmod(Storage::disk('public')->path(dirname($relativePath)), 0775);
177	        chmod(Storage::disk('public')->path(dirname($relativePath) . '/' . $finalName), 0644);
178	
179	        // update galleries record
180	        $file->image = $finalName;
181	        $file->path = $relativePath;
182	        $file->url = $relativePath;
183	        $file->extra = ['remote_name' => $this->remoteFieldName, 'locale' => $this->locale, 'token' => $remoteValue['token']];
184	        $file->position = 1;
185	        $file->save();
186	
187	        // create thumbs , only for images
188	        if (!empty($this->config[$this->localFieldName]['size'])) {
189	            $dirPath =  dirname(Storage::disk('public')->path($relativePath));
190	            foreach ($this->config[$this->localFieldName]['size'] as $kSize => $size) :
191	                copy($dirPath . '/' . $finalName, $dirPath . '/' . $kSize . $finalName);
192	                $fileService->resizeIMG($dirPath . '/' . $kSize . $finalName, $size['W'], $size['H'], $size['SW'], $size['SH'], $size['CROP'], $size['compression']);
193	            endforeach;
194	        }
195	
196	        // log action
197	        Log::channel('onpage')->info('image updated', [
198	            'gallery id' => $file->id
199	        ]);
200	
201	        return 1;
202	    }
203	}
