3	namespace Livewire\Features\SupportLifecycleHooks;
4	
5	use function Livewire\store;
6	use function Livewire\wrap;
7	use Livewire\ComponentHook;
8	
9	class SupportLifecycleHooks extends ComponentHook
10	{
11	    public function mount($params)
12	    {
13	        if (store($this->component)->has('skipMount')) { return; }
14	
15	        $this->callHook('boot');
16	        $this->callTraitHook('boot');
17	
18	        $this->callTraitHook('initialize');
19	
20	        $this->callHook('mount', $params);
21	        $this->callTraitHook('mount', $params);
22	
23	        $this->callHook('booted');
24	        $this->callTraitHook('booted');
25	    }
26	
27	    public function hydrate()
28	    {
29	        if (store($this->component)->has('skipHydrate')) { return; }
30	
31	        $this->callHook('boot');
32	        $this->callTraitHook('boot');
33	
34	        $this->callTraitHook('initialize');
35	
36	        $this->callHook('hydrate');
37	        $this->callTraitHook('hydrate');
38	
39	        // Call "hydrateXx" hooks for each property...
40	        foreach ($this->getProperties() as $property => $value) {
41	            $this->callHook('hydrate'.str($property)->studly(), [$value]);
42	        }
43	
44	        $this->callHook('booted');
45	        $this->callTraitHook('booted');
46	    }
47	
48	    public function update($propertyName, $fullPath, $newValue)
49	    {
50	        $name = str($fullPath);
51	
52	        $propertyName = $name->studly()->before('.');
53	        $keyAfterFirstDot = $name->contains('.') ? $name->after('.')->__toString() : null;
54	        $keyAfterLastDot = $name->contains('.') ? $name->afterLast('.')->__toString() : null;
55	
56	        $beforeMethod = 'updating'.$propertyName;
57	        $afterMethod = 'updated'.$propertyName;
58	
59	        $beforeNestedMethod = $name->contains('.')
60	            ? 'updating'.$name->replace('.', '_')->studly()
61	            : false;
62	
63	        $afterNestedMethod = $name->contains('.')
64	            ? 'updated'.$name->replace('.', '_')->studly()
65	            : false;
66	
67	        $this->callHook('updating', [$fullPath, $newValue]);
68	        $this->callTraitHook('updating', [$fullPath, $newValue]);
69	
70	        $this->callHook($beforeMethod, [$newValue, $keyAfterFirstDot]);
71	
72	        $this->callHook($beforeNestedMethod, [$newValue, $keyAfterLastDot]);
73	
74	        return function () use ($fullPath, $afterMethod, $afterNestedMethod, $keyAfterFirstDot, $keyAfterLastDot, $newValue) {
75	            $this->callHook('updated', [$fullPath, $newValue]);
76	            $this->callTraitHook('updated', [$fullPath, $newValue]);
77	
78	            $this->callHook($afterMethod, [$newValue, $keyAfterFirstDot]);
79	
80	            $this->callHook($afterNestedMethod, [$newValue, $keyAfterLastDot]);
81	        };
82	    }
83	
84	    public function call($methodName, $params, $returnEarly)
85	    {
86	        $protectedMethods = [
87	            'mount',
88	            'exception',
89	            'hydrate*',
90	            'dehydrate*',
91	            'updating*',
92	            'updated*',
93	        ];
94	
95	        throw_if(
96	            str($methodName)->is($protectedMethods),
97	            new DirectlyCallingLifecycleHooksNotAllowedException($methodName, $this->component->getName())
98	        );
99	
100	        $this->callTraitHook('call', ['methodName' => $methodName, 'params' => $params, 'returnEarly' => $returnEarly]);
101	    }
102	    
103	    public function exception($e, $stopPropagation)
104	    {
105	        $this->callHook('exception', ['e' => $e, 'stopPropagation' => $stopPropagation]);
106	        $this->callTraitHook('exception', ['e' => $e, 'stopPropagation' => $stopPropagation]);
107	    }
108	
109	    public function render($view, $data)
110	    {
111	        $this->callHook('rendering', ['view' => $view, 'data' => $data]);
112	        $this->callTraitHook('rendering', ['view' => $view, 'data' => $data]);
113	
114	        return function ($html) use ($view) {
115	            $this->callHook('rendered', ['view' => $view, 'html' => $html]);
116	            $this->callTraitHook('rendered', ['view' => $view, 'html' => $html]);
117	        };
118	    }
119	
