/**
 * Estrapolo dalla configurazione alcune informazioni
 * valorizzandole come proprietà del componente.
 */
protected function parseConfig()
{
    $config = $this->config;

    // regole di default per validazione
    if (!array_key_exists('rules', $config)) {
        $config['rules'] = $this->defaultRules();
    }


    // eventuali campi aggiuntivi
    $this->langFields = array_key_exists('lang_fields', $config) ? $config['lang_fields'] : [];
    $this->fields = array_key_exists('fields', $config) ? $config['fields'] : [];

    // file non sostituibile/cancellabile da qui (es. sincronizzato da fonte esterna)
    $this->readonlyFile = array_key_exists('readonly_file', $config) ? (bool) $config['readonly_file'] : false;

    // memorizzo lista locales e id corrente
    $this->currentLgId = current(array_keys($this->langList));

    // aggiorno alcune informazioni per assecondare vista
    //$this->file->values_tmp = $this->file->values;
    $this->fieldsValues = $this->file->values;
    foreach ($this->file->langs as $k => $rsLang) {
        $this->langFieldsValues[$rsLang->lang] = $rsLang->values;
    }

