207	     */
208	    public function loadFile($name, $parent_lang = null, $localeId = null)
209	    {
210	        $parent_lang = $parent_lang ?: 0;
211	
212	        if (array_key_exists($name . '_' . $parent_lang, $this->filesList)) {
213	            return $this->filesList[$name . '_' . $parent_lang];
214	        }
215	
216	        // le immagini ufficiali sono quelle con la colonna "image" valorizzata
217	        $wheres = [
218	            ["item_id", $this->id],
219	            ["item_table", $this->table],
220	            ["item_type", $name],
221	            ["status", 'Y'],
222	        ];
223	
224	        if ($parent_lang) {
225	            $wheres[] = ["parent_lang", $parent_lang];
226	        }
227	
228	        $file =  Gallery::where($wheres);
229	
230	        // prova a recuperare la lingua dalla lingua del modello
231	        // catch nell'eventualità che il modello non abbia relazione lingua
