/**
 * Caricamento di un file.
 * @param $parent_lang id lingua a cui il file è associato, nella tabella principale (NON ha ripercussioni sulle didascalie in lingua del file!)
 * @param $localeId locale in cui caricare le lingue del file
 * Se non passato, recupera il file indipendentemente dalla sua associazione con una lingua della voce padre.
 */
public function loadFile($name, $parent_lang = null, $localeId = null)
{
    $parent_lang = $parent_lang ?: 0;

    if (array_key_exists($name . '_' . $parent_lang, $this->filesList)) {
        return $this->filesList[$name . '_' . $parent_lang];
    }

    // le immagini ufficiali sono quelle con la colonna "image" valorizzata
    $wheres = [
        ["item_id", $this->id],
        ["item_table", $this->table],
        ["item_type", $name],
        ["status", 'Y'],
    ];

    if ($parent_lang) {
        $wheres[] = ["parent_lang", $parent_lang];
    }

    $file =  Gallery::where($wheres);

    // prova a recuperare la lingua dalla lingua del modello
    // catch nell'eventualità che il modello non abbia relazione lingua
    try {
        if($localeId === null && isset($this->current_lang) && $this->current_lang->lang) {
            $localeId =  $this->current_lang->lang;
        }
    } catch (Throwable) {

    }

    if($localeId) {
        $file->with(["langs" => function ($query) use ($localeId) {
            return $query->where([["lang", $localeId]]);
        }]);
    }

    $file = $file->first();

    $this->filesList[$name . '_' . $parent_lang] = $file;

    return $file;
}


public function getFileUrl($name, $parent_lang = null)
{
    $file = $this->loadFile($name, $parent_lang);

    return $file ? $file->url : null;
}


/**
 * Immagine
 */
public function image($index, $size = 'S', $parent_lang = null): ?string
{
    $index = is_numeric($index) ? "img_" . $index : $index;

    $file = $this->loadFile($index, $parent_lang);

